-- Versioned sector profiles; only metadata is readable by authenticated users.
create table if not exists navo_private.form_profiles(id text primary key,profile jsonb not null);
alter table navo_private.form_profiles enable row level security;
drop policy if exists form_metadata_read on navo_private.form_profiles;
