create or replace function navo_private.form_case_guard() returns trigger language plpgsql security invoker set search_path='' as $$
declare f jsonb; v jsonb; textvalue text; platform text; compared jsonb;
begin
 if new.body ? 'formId' then
  select profile into f from navo_private.form_profiles where id=new.body->>'formId';
  if f is null then raise exception 'Unknown form profile'; end if;
  select coalesce(p.platform,'Construction') into platform from public.projects p where p.id=new.project;
  if f->>'base'<>new.case_type or f->>'platform'<>platform then raise exception 'Choose a form matching the project platform and case type'; end if;
  if TG_OP='UPDATE' and old.status<>'Draft' and old.body->>'formId' is distinct from new.body->>'formId' then raise exception 'Submitted form identity cannot change'; end if;
  new.body:=jsonb_set(new.body,'{formName}',f->'name');
  if new.status<>'Draft' then
   for v in select value from jsonb_array_elements(f->'fields') loop
    textvalue:=new.body->>(v->>'key');
    if (v->>'required')::boolean and coalesce(trim(textvalue),'')='' then raise exception 'Required: %',v->>'label'; end if;
    if coalesce(textvalue,'')<>'' then
     if v->>'kind'='number' and textvalue !~ '^[0-9]+([.][0-9]+)?$' then raise exception 'Non-negative finite number required: %',v->>'label'; end if;
     if v->>'kind'='select' and not (v->'options' ? textvalue) then raise exception 'Invalid option: %',v->>'label'; end if;
     if v->>'kind'='month' and textvalue !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then raise exception 'Valid reporting month required'; end if;
     if v->>'kind'='date' then perform textvalue::date; end if;
    end if;
   end loop;
   if new.body ? 'periodStart' and new.body ? 'periodEnd' and (new.body->>'periodStart')::date>(new.body->>'periodEnd')::date then raise exception 'Reporting period end precedes start'; end if;
  end if;
 elsif TG_OP='UPDATE' and old.body ? 'formId' and old.status<>'Draft' then raise exception 'Submitted form profile cannot be removed';
 end if;
 if new.status<>'Draft' and new.body->>'highPotential'='Yes' and coalesce(trim(new.body->>'highPotentialReason'),'')='' then raise exception 'Describe the high-potential scenario'; end if;
 if coalesce(new.body->>'rcaReviewed','false')='true' then
  if jsonb_typeof(new.body->'rcaDocument') is distinct from 'object' then raise exception 'An investigation document is required'; end if;
  if TG_OP='UPDATE' and old.body->>'rcaReviewed'='true' then
   compared:=new.body-array['rcaReviewed','rcaReviewedBy','rcaReviewedAt'];
   if compared is distinct from old.body-array['rcaReviewed','rcaReviewedBy','rcaReviewedAt'] or new.title is distinct from old.title or new.project is distinct from old.project then
    new.body:=(new.body-array['rcaReviewedBy','rcaReviewedAt'])||jsonb_build_object('rcaReviewed',false);
   else new.body:=new.body||jsonb_build_object('rcaReviewedBy',old.body->'rcaReviewedBy','rcaReviewedAt',old.body->'rcaReviewedAt'); end if;
  else
   if not(public.is_admin() or public.my_role()='hse') then raise exception 'Investigator review requires HSE staff'; end if;
   new.body:=new.body||jsonb_build_object('rcaReviewedBy',auth.uid(),'rcaReviewedAt',now());
  end if;
 else new.body:=new.body-array['rcaReviewedBy','rcaReviewedAt']; end if;
 return new;
end $$;
revoke all on function navo_private.form_case_guard() from public;
grant execute on function navo_private.form_case_guard() to authenticated;
drop trigger if exists navo_case_a_form_guard on public.navo_cases;
create trigger navo_case_a_form_guard before insert or update on public.navo_cases for each row execute function navo_private.form_case_guard();
create or replace function navo_private.form_case_projection() returns trigger language plpgsql security invoker set search_path='' as $$
declare f jsonb;
begin
 if new.status='Draft' or not(new.body ? 'formId') then return new; end if;
 select profile into f from navo_private.form_profiles where id=new.body->>'formId';
 if new.case_type in ('Audit','Audit finding','Meeting') then
  insert into public.hsse_records(id,project,kind,ts,data,created_by) values(new.id,new.project,f->>'kind',(extract(epoch from new.created_at)*1000)::bigint,new.body||jsonb_build_object('title',new.title,'status',new.status,'caseId',new.id,'caseNo',new.case_no,'formUpdatedAt',new.updated_at),new.created_by) on conflict(id) do update set kind=excluded.kind,data=excluded.data;
 end if;
 return new;
end $$;
revoke all on function navo_private.form_case_projection() from public;
grant execute on function navo_private.form_case_projection() to authenticated;
drop trigger if exists navo_case_zz_form_projection on public.navo_cases;
create trigger navo_case_zz_form_projection after insert or update on public.navo_cases for each row execute function navo_private.form_case_projection();
